/**
 * Tiny deterministic glTF 2.0 GLB factory — web integration fallback only.
 * Canonical editable masters are generated by Blender via blender_factory.py.
 * Exports geometry shared by material: low draw-call overhead and no textures.
 * All model geometry is Y-up, ground y=0, front +Z, dimensions in meters.
 */
import fs from "node:fs";
import path from "node:path";
import crypto from "node:crypto";
import {fileURLToPath} from "node:url";
import {buildBrickhouseModernist,brickhouseAnchors,brickhouseSlots,BRICKHOUSE_ARCHETYPE} from "./brickhouse-modernism.mjs";
import {buildCityModernist,cityAnchors,cityMediaSlots,CITY_ARCHITECTURE_FAMILIES} from "./city-modernism.mjs";
import {pbrMaterials,MATERIAL_ROLE,MATERIAL_SYSTEM_VERSION} from "./material-system.mjs";

const root=path.resolve(path.dirname(fileURLToPath(import.meta.url)),"../..");
const cfg=JSON.parse(fs.readFileSync(path.join(root,"assets/specs/city-all.modernism.json"),"utf8"));
const dest=path.join(root,"public/assets/mt-city",cfg.version);
const prng=n=>{let s=n>>>0;return()=>((s=Math.imul(1664525,s)+1013904223>>>0)/4294967296)};
const align=n=>(n+3)&~3;
const textBytes=s=>Buffer.from(s,"utf8");
function geometry(asset,lod){
 const materials=pbrMaterials(asset);
 const rnd=prng(asset.seed);
 const buckets=materials.map(()=>({positions:[],normals:[],indices:[],triangles:0}));
 function cuboid(cx,cy,cz,w,h,d,m){
  if(w<=0||h<=0||d<=0)return;
  const x0=cx-w/2,x1=cx+w/2,y0=cy-h/2,y1=cy+h/2,z0=cz-d/2,z1=cz+d/2;
  const faces=[
   {n:[0,0,1],v:[[x0,y0,z1],[x1,y0,z1],[x1,y1,z1],[x0,y1,z1]]},
   {n:[0,0,-1],v:[[x1,y0,z0],[x0,y0,z0],[x0,y1,z0],[x1,y1,z0]]},
   {n:[-1,0,0],v:[[x0,y0,z0],[x0,y0,z1],[x0,y1,z1],[x0,y1,z0]]},
   {n:[1,0,0],v:[[x1,y0,z1],[x1,y0,z0],[x1,y1,z0],[x1,y1,z1]]},
   {n:[0,1,0],v:[[x0,y1,z1],[x1,y1,z1],[x1,y1,z0],[x0,y1,z0]]},
   {n:[0,-1,0],v:[[x0,y0,z0],[x1,y0,z0],[x1,y0,z1],[x0,y0,z1]]}
  ];
  const out=buckets[m];for(const face of faces){const index=out.positions.length/3;for(const p of face.v){out.positions.push(...p);out.normals.push(...face.n)}out.indices.push(index,index+1,index+2,index,index+2,index+3);out.triangles+=2}
 }
 if(asset.archetype==="brickhouse"&&asset.id==="office-brick")buildBrickhouseModernist(cuboid,asset,lod);
 else if(CITY_ARCHITECTURE_FAMILIES.includes(asset.archetype))buildCityModernist(cuboid,asset,lod);
 else throw Error("No approved modernist geometry: "+asset.id+" / "+asset.archetype);
 return {buckets,materials,triangles:buckets.reduce((n,b)=>n+b.triangles,0)};
}
function glb(asset,lod){
 const {buckets,materials,triangles}=geometry(asset,lod);
 const raw=[];let offset=0;
 const bufferViews=[],accessors=[],primitives=[];
 const push=(bytes,target)=>{const pad=align(bytes.length)-bytes.length;const view={buffer:0,byteOffset:offset,byteLength:bytes.length,...(target?{target}:{})};const idx=bufferViews.push(view)-1;raw.push(bytes);if(pad)raw.push(Buffer.alloc(pad));offset+=bytes.length+pad;return idx};
 const vec=(list)=>{const b=Buffer.alloc(list.length*4);for(let i=0;i<list.length;i++)b.writeFloatLE(list[i],i*4);return b};
 const index16=list=>{const b=Buffer.alloc(list.length*2);for(let i=0;i<list.length;i++)b.writeUInt16LE(list[i],i*2);return b};
 const accessor=(v,count,type,componentType,min,max)=>{const i=accessors.push({bufferView:v,componentType,count,type,...(min?{min}:{}),...(max?{max}:{})})-1;return i};
 for(let mi=0;mi<buckets.length;mi++){
  const b=buckets[mi];if(!b.indices.length)continue;
  if(b.positions.length/3>=65535)throw Error("Excess vertex count");
  const all=[[],[],[]];for(let i=0;i<b.positions.length;i+=3){for(let j=0;j<3;j++)all[j].push(b.positions[i+j])}
  const aP=accessor(push(vec(b.positions),34962),b.positions.length/3,"VEC3",5126,all.map(x=>Math.min(...x)),all.map(x=>Math.max(...x)));
  const aN=accessor(push(vec(b.normals),34962),b.normals.length/3,"VEC3",5126);
  const aI=accessor(push(index16(b.indices),34963),b.indices.length,"SCALAR",5123);
  primitives.push({attributes:{POSITION:aP,NORMAL:aN},indices:aI,material:mi,mode:4});
 }
 const anchors=(Object.entries(asset.id==="office-brick"?brickhouseAnchors(asset):cityAnchors(asset)))
 .map(([name,translation])=>({name,translation,...(name==="COLLIDER_Footprint"?{extras:{width:asset.width,depth:asset.depth,height:asset.height}}:{})}));
 const slots=asset.id==="office-brick"?brickhouseSlots(asset):cityMediaSlots(asset);
 const json={
  asset:{version:"2.0",generator:"Marketing Tycoon Reproducible Web Fallback (not Blender)"},
  scene:0,scenes:[{nodes:[0]}],
  nodes:[{name:"MT_MASTER_"+asset.id,children:Array.from({length:1+anchors.length},(_,i)=>i+1),extras:{persistentGameEntity:asset.gameplayId||null,assetId:asset.id,lod}}, {name:"VISIBLE_MESH",mesh:0},...anchors],
  meshes:[{name:"merged_facade",primitives}],bufferViews,accessors,buffers:[{byteLength:offset}],
  materials,
  extras:{id:asset.id,version:cfg.version,source:"node-fallback",materialSystem:MATERIAL_SYSTEM_VERSION,height:asset.height,width:asset.width,depth:asset.depth,triangles,tier:asset.tier??1,archetype:asset.id==="office-brick"?BRICKHOUSE_ARCHETYPE:asset.archetype,advertisingSlots:slots}
 };
 const jsonBytes=textBytes(JSON.stringify(json));
 const j=Buffer.concat([jsonBytes,Buffer.alloc(align(jsonBytes.length)-jsonBytes.length,0x20)]);
 const bin=Buffer.concat(raw);
 const header=Buffer.alloc(12);header.writeUInt32LE(0x46546c67,0);header.writeUInt32LE(2,4);header.writeUInt32LE(12+8+j.length+8+bin.length,8);
 const chunkA=Buffer.alloc(8);chunkA.writeUInt32LE(j.length,0);chunkA.writeUInt32LE(0x4e4f534a,4);
 const chunkB=Buffer.alloc(8);chunkB.writeUInt32LE(bin.length,0);chunkB.writeUInt32LE(0x004e4942,4);
 return {buffer:Buffer.concat([header,chunkA,j,chunkB,bin]),triangles,primitiveCount:primitives.length};
}
export function parseGLB(buffer){
 if(buffer.length<28||buffer.readUInt32LE(0)!==0x46546c67||buffer.readUInt32LE(4)!==2||buffer.readUInt32LE(8)!==buffer.length)throw Error("Invalid GLB header");
 if(buffer.readUInt32LE(16)!==0x4e4f534a)throw Error("Invalid GLB JSON chunk");
 const j=JSON.parse(buffer.subarray(20,20+buffer.readUInt32LE(12)).toString("utf8"));
 if(!j.nodes?.length||!j.meshes?.length)throw Error("Missing geometry");
 const names=new Set(j.nodes.map(x=>x.name));
 for(const a of ["ANCHOR_Entrance","ANCHOR_Sign","ANCHOR_Roof","COLLIDER_Footprint"])if(!names.has(a))throw Error("Missing "+a);
 const bounds=j.accessors.filter(a=>a.type==="VEC3"&&Array.isArray(a.min));
 for(const a of bounds)if(a.min.some((x,i)=>x>a.max[i]||!Number.isFinite(x)))throw Error("Bad bounds");
 return j;
}
function main(){
 fs.mkdirSync(dest,{recursive:true});
 const ids=new Set(),out=[],qa=[];let extraTierFiles=0,extraTierBytes=0,extraTierTris=0;
 const sampleOnly=process.argv.includes("--sample");
 const representativeIds=new Set(["office-brick","client-bloom","rival-muse","creative","arts-residence-a","office-tower"]);
 const chosen=sampleOnly?cfg.masters.filter(x=>representativeIds.has(x.id)):cfg.masters;
 if(sampleOnly&&chosen.length!==representativeIds.size)throw Error("Incomplete six-asset PBR QA sample");
 if(cfg.masters.length!==cfg.auditedBuildingCount||cfg.masters.length!==41)throw Error("Incomplete whole-city manifest; expected all audited building instances");
 for(const a of chosen){
  if(ids.has(a.id))throw Error("Duplicate ID: "+a.id);ids.add(a.id);
  if(!Number.isInteger(a.seed)||a.width<=0||a.height<=0||a.depth<=0||a.floors<1)throw Error("Invalid asset spec "+a.id);
  const lod={};for(const mode of [0,1]){
   const data=glb(a,mode);const budget=mode===0?1800:360;
   if(data.triangles>budget)throw Error(a.id+" LOD"+mode+" triangle budget exceeded "+data.triangles);
   const name=a.id+".lod"+mode+".glb";
   const file=path.join(dest,name);
   if(process.argv.includes("--verify")){
    if(!fs.existsSync(file)||!fs.readFileSync(file).equals(data.buffer))throw Error("Non-reproducible or missing binary "+name);
   }else fs.writeFileSync(file,data.buffer);
   const parsed=parseGLB(data.buffer);
   if(parsed.extras.id!==a.id||parsed.extras.height!==a.height)throw Error("Metadata mismatch "+a.id);
   if(parsed.extras.materialSystem!==MATERIAL_SYSTEM_VERSION)throw Error("Missing PBR material metadata "+a.id);
   if(parsed.materials.length!==11||parsed.materials[MATERIAL_ROLE.WINDOW_GLASS].pbrMetallicRoughness.roughnessFactor>=.40)throw Error("Missing PBR glass "+a.id);
   for(const slot of a.id==="office-brick"?brickhouseSlots(a):cityMediaSlots(a)){if(!parsed.nodes.some(x=>x.name===slot.anchor))throw Error("Missing media anchor "+slot.id)}
   if(a.id==="office-brick"){
    if(parsed.extras.archetype!==BRICKHOUSE_ARCHETYPE)throw Error("Brickhouse modernist archetype missing");
    for(const slot of brickhouseSlots(a)){
      if(!parsed.nodes.some(x=>x.name===slot.anchor))throw Error("Missing modernist media anchor: "+slot.anchor);
    }
   }
   lod["lod"+mode]={uri:"/assets/mt-city/"+cfg.version+"/"+name,triangles:data.triangles,bytes:data.buffer.length,materials:data.primitiveCount,sha256:crypto.createHash("sha256").update(data.buffer).digest("hex")};
  }
  if(lod.lod1.triangles>lod.lod0.triangles)throw Error("Invalid LOD detail order for "+a.id+": low "+lod.lod1.triangles+" > high "+lod.lod0.triangles);
  // Expansion stages of each of the five actual rival agencies are separate 3D assets.
  const tiers={};
  if(a.class==="rival")for(let tier=2;tier<=4;tier++){
   const stage={...a,tier},stageLod={};
   for(const mode of [0,1]){
    const data=glb(stage,mode);
    if(data.triangles>(mode===0?1800:360))throw Error("Rival stage exceeds budget "+a.id+" T"+tier+" LOD"+mode);
    const name=a.id+".tier"+tier+".lod"+mode+".glb",file=path.join(dest,name);
    if(process.argv.includes("--verify")){
     if(!fs.existsSync(file)||!fs.readFileSync(file).equals(data.buffer))throw Error("Missing or inconsistent expansion GLB "+name);
    }else fs.writeFileSync(file,data.buffer);
    const parsed=parseGLB(data.buffer);
    if(parsed.extras.id!==a.id||parsed.extras.tier!==tier)throw Error("Rival tier metadata mismatch");
    stageLod["lod"+mode]={uri:"/assets/mt-city/"+cfg.version+"/"+name,triangles:data.triangles,bytes:data.buffer.length,sha256:crypto.createHash("sha256").update(data.buffer).digest("hex")};
    extraTierFiles++;extraTierBytes+=data.buffer.length;if(mode===0)extraTierTris+=data.triangles;
   }
   tiers["tier"+tier]=stageLod;
  }
  qa.push({id:a.id,kind:a.class,gameplayId:a.gameplayId||null,highTriangles:lod.lod0.triangles,lowTriangles:lod.lod1.triangles,highBytes:lod.lod0.bytes,lowBytes:lod.lod1.bytes});
  out.push({id:a.id,name:a.name,kind:a.class,gameplayId:a.gameplayId||null,decorative:!!a.decorative,district:a.district,
   position:[a.x,a.z],dimensions:[a.width,a.height,a.depth],footprint:[a.width,a.depth],previousAsset:a.priorAsset,
   anchors:Object.keys(a.id==="office-brick"?brickhouseAnchors(a):cityAnchors(a)),
   archetype:a.id==="office-brick"?BRICKHOUSE_ARCHETYPE:a.archetype,roof:a.roof,facade:a.facade,entrance:a.entrance,variant:a.variant,
   advertisingSlots:a.id==="office-brick"?brickhouseSlots(a):cityMediaSlots(a),
   migrationStatus:"replaced",verificationStatus:"binary-pass-browser-pending",materialSystem:MATERIAL_SYSTEM_VERSION,lod,tierLOD:tiers,palette:a.palette});
 }
 if(sampleOnly){
  if(out.length!==6||qa.some(x=>x.highTriangles>1800))throw Error("Six-asset material slice failed");
  console.log("PBR REPRESENTATIVE SLICE",JSON.stringify({validatedMasters:6,generatedPrimaryGLBs:12,representativeIds:[...representativeIds],materialSystem:MATERIAL_SYSTEM_VERSION}));
  return;
 }
 for(const d of cfg.decorativePlacements)if(!ids.has(d.id))throw Error("Missing placement asset "+d.id);
 const manifest={schemaVersion:2,version:cfg.version,district:cfg.district,units:"meters",up:"Y",front:"+Z",source:"web-fallback-not-blender",
 auditedBuildingCount:cfg.auditedBuildingCount,interactiveCount:cfg.auditedInteractiveCount,decorativeCount:cfg.auditedDecorativeCount,
 assets:out,decorativePlacements:cfg.decorativePlacements};
 const report={generatedAt:"reproducible-build",assetCount:qa.length,glbFiles:qa.length*2+extraTierFiles,extraTierFiles,extraTierBytes,extraTierTris,totalTrianglesHigh:qa.reduce((x,y)=>x+y.highTriangles,0),totalBytesHigh:qa.reduce((x,y)=>x+y.highBytes,0),totalBytesLow:qa.reduce((x,y)=>x+y.lowBytes,0),assets:qa,passed:true,measuredBrowserFPS:false,measuredBrowserDrawCalls:false};
 const mFile=path.join(dest,"manifest.json"),qFile=path.join(dest,"qa-report.json");
 if(process.argv.includes("--verify")){if(!fs.existsSync(mFile)||fs.readFileSync(mFile,"utf8")!==JSON.stringify(manifest,null,2)+"\n")throw Error("Manifest mismatch")}
 else{fs.writeFileSync(mFile,JSON.stringify(manifest,null,2)+"\n");fs.writeFileSync(qFile,JSON.stringify(report,null,2)+"\n")}
 console.log("ART FACTORY",JSON.stringify({district:cfg.district,masters:qa.length,interactive:cfg.auditedInteractiveCount,decorative:cfg.auditedDecorativeCount,glbs:qa.length*2+extraTierFiles,triangles:report.totalTrianglesHigh,bytes:report.totalBytesHigh+report.totalBytesLow+extraTierBytes,rivalTierVariants:extraTierFiles,verified:true}));
}
main();
